    correction: [{"quoi":"ننشر جداء القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a + 2)(b + 7) = ab + 7a + 2b + 14</span>"},{"quoi":"نجمع المعطيات","math":"<span dir=\"ltr\" class=\"expr\">ab = 390</span> و <span dir=\"ltr\" class=\"expr\">7a + 2b = 212</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">ab + 7a + 2b + 14 = 390 + 212 + 14</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">390 + 212 + 14 = 616</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">G = 616</span>"}],
